using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the current application configuration",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new
            {
                EnableCaching = true,
                MaxRetries = 3,
                TimeoutSeconds = 30,
            },
        };

        return JsonSerializer.Serialize(config, JsonOptions);
    }

    [McpServerResource(
        Uri = "config://app/endpoints",
        Name = "API Endpoints",
        Description = "Lists available API endpoints and their status",
        MimeType = "application/json")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Transport = "Streamable HTTP", Status = "Active" },
            new { Path = "/health", Transport = "REST", Status = "Active" },
        };

        return JsonSerializer.Serialize(endpoints, JsonOptions);
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets the current weather for a given city.")]
    public static string GetWeather(
        [Description("The city name, e.g. 'Seattle'")] string city)
    {
        // Stub implementation for demonstration
        var conditions = new[] { "Sunny", "Cloudy", "Rainy", "Snowy" };
        var temp = Random.Shared.Next(-10, 40);
        var condition = conditions[Random.Shared.Next(conditions.Length)];

        return $"Weather in {city}: {temp}°C, {condition}";
    }
}

