        Description = "Returns the current application configuration",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new
            {
                EnableCaching = true,
                MaxRetries = 3,
                TimeoutSeconds = 30,
            },
        };

        return JsonSerializer.Serialize(config, JsonOptions);
    }

    [McpServerResource(
        Uri = "config://app/endpoints",
        Name = "API Endpoints",
        Description = "Lists available API endpoints and their status",
        MimeType = "application/json")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Transport = "Streamable HTTP", Status = "Active" },
            new { Path = "/health", Transport = "REST", Status = "Active" },
        };

        return JsonSerializer.Serialize(endpoints, JsonOptions);
    }
}

